From: Mario Limonciello <mario.limonciello@dell.com>
Date: Thu, 13 Feb 2020 12:06:41 -0600
Subject: [PATCH] fu-util: fix a logic error in report uploading introduced in
 e076d48afb74d1447936d353f12781755f13b047

Fixes: #1770

diff --git a/src/fu-util.c b/src/fu-util.c
index 5bcffedeb..e6531c90c 100644
--- a/src/fu-util.c
+++ b/src/fu-util.c
@@ -286,16 +286,12 @@ fu_util_maybe_enable_automatic (FuUtilPrivate *priv, GPtrArray *remotes, GError
 							 NULL, error))
 				return FALSE;
 		}
-		return TRUE;
+		break;
 	default:
 		break;
 	}

-	g_set_error_literal (error,
-			     FWUPD_ERROR,
-			     FWUPD_ERROR_NOTHING_TO_DO,
-			     "invalid option selected");
-	return FALSE;
+	return TRUE;
 }

 static gboolean
-- 
2.25.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
fu-util: fix a logic error in report uploading introduced in
 e076d48afb74d1447936d353f12781755f13b047

Fixes: #1770

Here is the root cause:
The bug was caused by a logic error in the `fu_util_maybe_enable_automatic` function, where the function incorrectly returned `TRUE` unconditionally instead of properly handling different cases in the switch statement. This led to situations where the function would not report errors correctly, resulting in unintended behavior during report uploading.

Here is the patch:

 static gboolean
 fu_util_maybe_enable_automatic (FuUtilPrivate *priv, GPtrArray *remotes, GError **error)
 {
 	guint idx;

 	/* TRANSLATORS: Display a message asking every time an update is performed */
 	g_print ("%d.\t%s\n",
 		 FU_UTIL_HISTORY_DO_NOTHING,
 		 ngettext ("Do not upload report at this time, but prompt again for future updates",
 			   "Do not upload reports at this time, but prompt again for future updates",
 			   remotes->len));
 	/* TRANSLATORS: Display a message asking every time an update is performed */
 	g_print ("%d.\t%s\n",
 		 FU_UTIL_HISTORY_NEVER,
 		 ngettext ("Do not upload report, and never ask to upload reports for future updates",
 			   "Do not upload reports, and never ask to upload reports for future updates",
 			   remotes->len));
 	/* TRANSLATORS: Display a message asking every time an update is performed */
 	g_print ("%d.\t%s\n",
 		 FU_UTIL_HISTORY_PROMPT,
 		 ngettext ("Upload report just this one time, but prompt again for future updates",
 			   "Upload reports just this one time, but prompt again for future updates",
 			   remotes->len));
 	/* TRANSLATORS: Display a message asking every time an update is performed */
 	g_print ("%d.\t%s\n",
 		 FU_UTIL_HISTORY_AUTOMATIC,
 		 ngettext ("Upload report this time and automatically upload reports after completing future updates",
 			   "Upload reports this time and automatically upload reports after completing future updates",
 			   remotes->len));
 	idx = fu_util_prompt_for_number (FU_UTIL_HISTORY_LAST - 1);

 	switch (idx) {
 	case FU_UTIL_HISTORY_NEVER:
 		for (guint i = 0; i < remotes->len; i++) {
 			FwupdRemote *remote = g_ptr_array_index (remotes, i);
 			const gchar *remote_id = fwupd_remote_get_id (remote);
 			if (fwupd_remote_get_report_uri (remote) == NULL)
 				continue;
 			if (!fwupd_client_modify_remote (priv->client,
 							 remote_id, "ReportURI", "",
 							 NULL, error))
 				return FALSE;
 		}
 		g_set_error_literal (error,
 				     FWUPD_ERROR,
 				     FWUPD_ERROR_NOTHING_TO_DO,
 				     "Reporting disabled");
 		return FALSE;
 	case FU_UTIL_HISTORY_DO_NOTHING:
 		g_set_error_literal (error,
 				     FWUPD_ERROR,
 				     FWUPD_ERROR_NOTHING_TO_DO,
 				     "Request canceled");
 		return FALSE;
 	case FU_UTIL_HISTORY_AUTOMATIC:
 		for (guint i = 0; i < remotes->len; i++) {
 			FwupdRemote *remote = g_ptr_array_index (remotes, i);
 			const gchar *remote_id = fwupd_remote_get_id (remote);
 			if (fwupd_remote_get_report_uri (remote) == NULL)
 				continue;
 			if (fwupd_remote_get_automatic_reports (remote))
 				continue;
 			if (!fwupd_client_modify_remote (priv->client,
 							 remote_id, "AutomaticReports", "true",
 							 NULL, error))
 				return FALSE;
 		}
-		return TRUE;
+		break;
 	default:
 		break;
 	}

-	g_set_error_literal (error,
-			     FWUPD_ERROR,
-			     FWUPD_ERROR_NOTHING_TO_DO,
-			     "invalid option selected");
-	return FALSE;
+	return TRUE;
 }



